100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    /**
126	     * Rejects an owner payload that is missing or blank in any of the required fields
127	     * (firstName, lastName, address, city, telephone). Bean Validation on the request body
128	     * already rejects {@code null} values and empty strings, but treats a whitespace-only
129	     * value as present; this guard closes that gap so a blank in any required field is
130	     * reported. The thrown exception is translated to a 400 whose {@code errors} array lists
131	     * the name of each offending field.
132	     */
133	    private void rejectMissingOrBlankFields(OwnerFieldsDto ownerFieldsDto, String normalizedAddress) {
134	        List<String> missing = new ArrayList<>();
135	        if (isBlank(ownerFieldsDto.getFirstName())) {
136	            missing.add("firstName");
137	        }
138	        if (isBlank(ownerFieldsDto.getLastName())) {
139	            missing.add("lastName");
140	        }
141	        if (isBlank(normalizedAddress)) {
142	            missing.add("address");
143	        }
144	        if (isBlank(ownerFieldsDto.getCity())) {
145	            missing.add("city");
146	        }
147	        if (isBlank(ownerFieldsDto.getTelephone())) {
148	            missing.add("telephone");
149	        }
150	        if (!missing.isEmpty()) {
151	            throw new MissingOwnerFieldsException(missing);
152	        }
153	    }
154	
155	    private static boolean isBlank(String value) {
156	        return value == null || value.isBlank();
157	    }
158	
159	    /**
160	     * Matches a well-formed E.164 telephone: a leading '+' followed by 8 to 15 digits.
161	     */
162	    private static final Pattern E164_PATTERN = Pattern.compile("\\+\\d{8,15}");
163	
164	    /**
165	     * Required national-number length per country calling code. When the normalized E.164 number
166	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
167	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
168	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
169	     */
170	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
171	        "+61", 9,
172	        "+1", 10);
173	
174	    /**
175	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
176	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
177	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
178	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
179	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
180	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
181	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
182	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
183	     * translates to a 400.
184	     */
185	    private static String normalizeTelephone(String telephone) {
186	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
187	        String e164;
188	        if (cleaned.startsWith("+")) {
189	            e164 = cleaned;
190	        } else {
191	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
192	            e164 = "+61" + national;
193	        }
194	        if (!E164_PATTERN.matcher(e164).matches()) {
195	            throw new InvalidTelephoneException(telephone);
196	        }
197	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
198	            String code = rule.getKey();
199	            if (e164.startsWith(code)) {
200	                int nationalLength = e164.length() - code.length();
201	                if (nationalLength != rule.getValue()) {
202	                    throw new InvalidTelephoneException(telephone);
203	                }
204	                break;
205	            }
206	        }
207	        return e164;
208	    }
209	
210	    /**
211	     * Matches a well-formed postcode: exactly four digits.
212	     */
213	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
214	
215	    /**
216	     * The canonical region for each city that has one. A city absent from this table has no known
217	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
218	     * to derive an owner's locality.
219	     */
220	    private static final Map<String, String> CITY_REGION = Map.of(
221	        "Sydney", "NSW",
222	        "Melbourne", "VIC",
223	        "Brisbane", "QLD");
224	
225	    /**
226	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
227	     * VIC 3000-3099, QLD 4000-4099.
228	     */
229	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
230	        "NSW", new int[] {2000, 2099},
231	        "VIC", new int[] {3000, 3099},
232	        "QLD", new int[] {4000, 4099});
233	
234	    /**
235	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
236	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
237	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
238	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
239	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
240	     * exception handler translates to a 400.
241	     */
242	    private static void validatePostcode(String city, String postcode) {
243	        if (postcode == null) {
244	            return;
245	        }
246	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
247	            throw new InvalidPostcodeException(postcode);
248	        }
249	        String region = CITY_REGION.get(city);
250	        if (region == null) {
251	            return;
252	        }
253	        int[] range = REGION_POSTCODES.get(region);
254	        int value = Integer.parseInt(postcode);
255	        if (value < range[0] || value > range[1]) {
256	            throw new InvalidPostcodeException(postcode);
257	        }
258	    }
259	
260	    /**
261	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
262	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
263	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
264	     */
265	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
266	
267	    /**
268	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
269	     * optional). When present it must be a syntactically valid address; a valid value is
270	     * lower-cased so it is stored and returned in canonical form. An invalid value is rejected via
271	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
272	     */
273	    private static String normalizeEmail(String email) {
274	        if (email == null) {
275	            return null;
276	        }
277	        if (!EMAIL_PATTERN.matcher(email).matches()) {
278	            throw new InvalidEmailException(email);
279	        }
280	        return email.toLowerCase(Locale.ROOT);
281	    }
282	
283	    /**
284	     * The single derived identity of an owner, {@code normalizedTelephone + '|' + (email or empty)
285	     * + '|' + householdId}, into which all duplicate detection is consolidated. Two owners are the
286	     * same identity only when this whole key matches: because the normalized telephone is part of
287	     * the key, two members of the same household (same {@code householdId}) with different
288	     * telephones have different identity keys. A {@code null} email contributes an empty middle
289	     * segment. This is the value returned to callers as {@code identityKey}.
290	     */
291	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String householdId) {
292	        return normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail) + "|" + householdId;
293	    }
294	
295	    /**
296	     * Rejects a create whose derived identity collides with an existing owner's, reported via one
297	     * of the {@code Duplicate*} exceptions the handler translates to a 409. The former separate
298	     * telephone, email and household checks are now expressed through the components of the single
299	     * identity key:
300	     * <ul>
301	     *   <li>the normalized telephone matches an existing owner's canonical E.164 telephone (an
302	     *       existing value that cannot form a valid E.164 number is skipped rather than colliding);</li>
303	     *   <li>a present, lower-cased email matches an existing owner's lower-cased email (a {@code null}
304	     *       candidate email, being optional, is not compared, and existing owners without an email
305	     *       are skipped);</li>
306	     *   <li>the {@code householdId} matches an existing owner's - unless the caller opted into sharing
307	     *       a household via {@code sharesHousehold}, in which case the household component is not
308	     *       compared.</li>
309	     * </ul>
310	     */
311	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
312	                                         String normalizedEmail, String householdId) {
313	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
314	        for (Owner existing : this.clinicService.findAllOwners()) {
315	            String existingTelephone;
316	            try {
317	                existingTelephone = normalizeTelephone(existing.getTelephone());
318	            } catch (InvalidTelephoneException ex) {
319	                existingTelephone = null;
320	            }
321	            if (normalizedTelephone.equals(existingTelephone)) {
322	                throw new DuplicateTelephoneException(normalizedTelephone);
323	            }
324	            if (normalizedEmail != null) {
325	                String existingEmail = existing.getEmail();
326	                if (existingEmail != null && normalizedEmail.equals(existingEmail.toLowerCase(Locale.ROOT))) {
327	                    throw new DuplicateEmailException(normalizedEmail);
328	                }
329	            }
330	            if (!sharesHousehold
331	                && householdId.equals(householdIdFor(existing.getLastName(), existing.getAddress()))) {
332	                throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
333	            }
334	        }
335	    }
336	
337	    /**
338	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
339	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
340	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
341	     * spacing do not defeat the duplicate-household check.
342	     */
343	    private static String collapse(String value) {
344	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
345	    }
346	
347	    /**
348	     * Normalizes an owner's address into a canonical form applied on every create: leading and
349	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
350	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
351	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
352	     * and returned, and is the form every address comparison (duplicate-household detection and the
353	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
354	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
355	     * so normalizing an already-normalized address is a no-op.
356	     */
357	    private static String normalizeAddress(String address) {
358	        if (address == null) {
359	            return "";
360	        }
361	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
362	        if (collapsed.isEmpty()) {
363	            return "";
364	        }
365	        String[] tokens = collapsed.split(" ");
366	        StringBuilder sb = new StringBuilder(collapsed.length());
367	        for (int i = 0; i < tokens.length; i++) {
368	            String token = tokens[i];
369	            switch (token) {
370	                case "ST" -> token = "STREET";
371	                case "RD" -> token = "ROAD";
372	                case "AVE" -> token = "AVENUE";
373	                default -> {
374	                }
375	            }
376	            if (i > 0) {
377	                sb.append(' ');
378	            }
379	            sb.append(token);
380	        }
381	        return sb.toString();
382	    }
383	
384	    /**
385	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
386	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
387	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
388	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
389	     * region derivation shared by the {@code customerCode} and the owner's locality.
390	     */
391	    private static String deriveRegion(String city, String postcode) {
392	        if (postcode != null) {
393	            try {
394	                int pc = Integer.parseInt(postcode.trim());
395	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
396	                    int[] bounds = range.getValue();
397	                    if (pc >= bounds[0] && pc <= bounds[1]) {
398	                        return range.getKey();
399	                    }
400	                }
401	            } catch (NumberFormatException ignored) {
402	                // not a numeric postcode; fall back to the city-to-region table
403	            }
404	        }
405	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
406	    }
407	
408	    /**
409	     * Builds the {@code customerCode} for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
410	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
411	     * city) and {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
412	     * {@code normalizedTelephone + lastName} (e.g. {@code 'NSW-1A2B3C4D'}). This is a stable identity:
413	     * it carries no sequence number and depends only on the owner's own region, telephone and surname.
414	     */
415	    private static String customerCodeFor(String region, String normalizedTelephone, String lastName) {
416	        return region + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
417	    }
418	
419	    /**
420	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
421	     * bytes of {@code value}.
422	     */
423	    private static String sha256HexPrefix(String value, int hexChars) {
424	        try {
425	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
426	            StringBuilder sb = new StringBuilder(hexChars);
427	            for (byte b : digest) {
428	                if (sb.length() >= hexChars) {
429	                    break;
430	                }
431	                sb.append(String.format("%02X", b));
432	            }
433	            return sb.substring(0, hexChars);
434	        } catch (NoSuchAlgorithmException ex) {
435	            throw new IllegalStateException("SHA-256 not available", ex);
436	        }
437	    }
438	
439	    /**
440	     * Builds the {@code membershipNumber} for a newly created owner, formatted
441	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
442	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
443	     */
444	    private static String membershipNumberFor(String customerCode, LocalDate registrationDate) {
445	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
446	    }
447	
448	    /**
449	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
450	     * {@code address} - the same pair used to detect a shared household. Because it is a pure
451	     * function of that pair (upper-case hex of SHA-256 over the two collapsed values), every owner
452	     * in the same household - whether created first or joining later via {@code sharesHousehold} -
453	     * receives the identical, non-blank identifier without needing to read any other owner's value.
454	     */
455	    private static String householdIdFor(String lastName, String address) {
456	        String key = collapse(lastName) + "\n" + normalizeAddress(address);
457	        try {
458	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
459	            StringBuilder sb = new StringBuilder(32);
460	            for (int i = 0; i < 8; i++) {
461	                sb.append(String.format("%02X", digest[i]));
462	            }
463	            return sb.toString();
464	        } catch (NoSuchAlgorithmException ex) {
465	            throw new IllegalStateException("SHA-256 not available", ex);
466	        }
467	    }
468	
469	    /**
470	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
471	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
472	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
473	     */
474	    private int countNamesakes(String firstName, String lastName) {
475	        int count = 0;
476	        for (Owner existing : this.clinicService.findAllOwners()) {
477	            if (firstName.equalsIgnoreCase(existing.getFirstName())
478	                && lastName.equalsIgnoreCase(existing.getLastName())) {
479	                count++;
480	            }
481	        }
482	        return count;
483	    }
484	
485	    /**
486	     * Counts the members of the household the new owner will belong to, as it stands after this
487	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
488	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
489	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
490	     * stored on the owner as its {@code householdMemberCount}.
491	     */
492	    private int countHouseholdMembers(String householdId) {
493	        int count = 1;
494	        for (Owner existing : this.clinicService.findAllOwners()) {
495	            if (householdId.equals(existing.getHouseholdId())) {
496	                count++;
497	            }
498	        }
499	        return count;
500	    }
501	
502	    /**
503	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
504	     * that is not a hard identity collision but shares the new owner's {@code lastName} (compared
505	     * case-insensitively) and {@code postcode} while carrying a different normalized telephone. The
506	     * new owner's postcode must be present for a soft match to be possible. When several existing
507	     * owners qualify the one with the lowest id is chosen. Returns the matching owner's id, or
508	     * {@code null} when there is no soft match. This is evaluated after the hard-duplicate check has
509	     * already passed, so any owner sharing the lastName and postcode necessarily differs in telephone.
510	     */
511	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone) {
512	        String postcode = ownerFieldsDto.getPostcode();
513	        if (postcode == null) {
514	            return null;
515	        }
516	        String lastName = ownerFieldsDto.getLastName();
517	        Integer matchId = null;
518	        for (Owner existing : this.clinicService.findAllOwners()) {
519	            if (lastName == null || !lastName.equalsIgnoreCase(existing.getLastName())) {
520	                continue;
521	            }
522	            if (!postcode.equals(existing.getPostcode())) {
523	                continue;
524	            }
525	            String existingTelephone;
526	            try {
527	                existingTelephone = normalizeTelephone(existing.getTelephone());
528	            } catch (InvalidTelephoneException ex) {
529	                existingTelephone = null;
530	            }
531	            if (normalizedTelephone.equals(existingTelephone)) {
532	                continue;
533	            }
534	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
535	                matchId = existing.getId();
536	            }
537	        }
538	        return matchId;
539	    }
540	
541	    /**
542	     * The membership level ceiling assigned on create; level 4 is reserved for tenure and so is
543	     * never reached here.
544	     */
545	    private static final int MAX_MEMBERSHIP_LEVEL = 3;
546	
547	    /**
548	     * Computes the numeric {@code membershipLevel} for a newly created owner. It starts at 1,
549	     * gains 1 when an email is present, gains 1 when the owner's {@code namesakeCount} is 0, and
550	     * is capped at {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure). Evaluated after
551	     * the owner's email and namesakeCount have been set.
552	     */
553	    private static int membershipLevelFor(Owner owner) {
554	        int level = 1;
555	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
556	            level++;
557	        }
558	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
559	            level++;
560	        }
561	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
562	    }
563	
564	    /**
565	     * The maximum number of owners any single city may contain. A create whose city already
566	     * holds this many owners is rejected.
567	     */
568	    private static final int CITY_CAPACITY = 50;
569	
570	    /**
571	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
572	     * compared case-insensitively - the same way the city is matched when building the
573	     * {@code customerCode} sequence. The count reflects the state prior to this create. A city
574	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
575	     * translates to a 409.
576	     */
577	    private void rejectCityAtCapacity(String city) {
578	        int count = 0;
579	        for (Owner existing : this.clinicService.findAllOwners()) {
580	            if (city.equalsIgnoreCase(existing.getCity())) {
581	                count++;
582	            }
583	        }
584	        if (count >= CITY_CAPACITY) {
585	            throw new CityAtCapacityException(city);
586	        }
587	    }
588	
589	    /**
590	     * The maximum number of owners that may be created on any single day (by
591	     * {@code registrationDate}). A create attempted once this many owners already carry the
592	     * current day's registration date is rejected.
593	     */
594	    private static final int DAILY_OWNER_LIMIT = 100;
595	
596	    /**
597	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
598	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
599	     * The count reflects the state prior to this create. When the limit is reached the create is
600	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
601	     * to a 429 Too Many Requests.
602	     */
603	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
604	        int count = 0;
605	        for (Owner existing : this.clinicService.findAllOwners()) {
606	            if (registrationDate.equals(existing.getRegistrationDate())) {
607	                count++;
608	            }
609	        }
610	        if (count >= DAILY_OWNER_LIMIT) {
611	            throw new DailyOwnerLimitExceededException();
612	        }
613	    }
614	
615	    /**
616	     * The number of owners that must already carry a given {@code registrationDate} before a
617	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
618	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
619	     */
620	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
621	
622	    /**
623	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
624	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
625	     * have already been created for that date, otherwise false. The count reflects the state prior
626	     * to this create, matching how the daily-limit rule accumulates.
627	     */
628	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
629	        int count = 0;
630	        for (Owner existing : this.clinicService.findAllOwners()) {
631	            if (registrationDate.equals(existing.getRegistrationDate())) {
632	                count++;
633	            }
634	        }
635	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
636	    }
637	
638	    /**
639	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is
640	     * advanced to the following Monday; a weekday is returned unchanged. This is applied to the
641	     * effective registration date - whether supplied in the request or defaulted to the server
642	     * date - so the stored {@code registrationDate}, and everything derived from it, always falls
643	     * on a business day.
644	     */
645	    /**
646	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
647	     * only ever explicitly supplied on the request; when present it must not be later than the
648	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
649	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
650	     * later from the server date) is accepted.
651	     */
652	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
653	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
654	            throw new FutureRegistrationDateException(registrationDate);
655	        }
656	    }
657	
658	    private static LocalDate toBusinessDay(LocalDate date) {
659	        return switch (date.getDayOfWeek()) {
660	            case SATURDAY -> date.plusDays(2);
661	            case SUNDAY -> date.plusDays(1);
662	            default -> date;
663	        };
664	    }
665	
666	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
667	    @Override
668	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
669	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
670	        rejectMissingOrBlankFields(ownerFieldsDto, normalizedAddress);
671	        rejectCityAtCapacity(ownerFieldsDto.getCity());
672	        HttpHeaders headers = new HttpHeaders();
673	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
674	        owner.setAddress(normalizedAddress);
675	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
676	        owner.setTelephone(normalizedTelephone);
677	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
678	        owner.setEmail(normalizedEmail);
679	        validatePostcode(owner.getCity(), owner.getPostcode());
680	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
681	        rejectDuplicateIdentity(ownerFieldsDto, normalizedTelephone, normalizedEmail, householdId);
682	        rejectFutureRegistrationDate(owner.getRegistrationDate());
683	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
684	        LocalDate registrationDate = toBusinessDay(effectiveDate);
685	        rejectDailyOwnerLimit(registrationDate);
686	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
687	        owner.setRegistrationDate(registrationDate);
688	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
689	        owner.setCustomerCode(customerCodeFor(region, normalizedTelephone, owner.getLastName()));
690	        owner.setMembershipNumber(membershipNumberFor(owner.getCustomerCode(), owner.getRegistrationDate()));
691	        owner.setHouseholdId(householdId);
692	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
693	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
694	        owner.setMembershipLevel(membershipLevelFor(owner));
695	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone);
696	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
697	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
698	        this.clinicService.saveOwner(owner);
699	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
700	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
701	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
702	        headers.setLocation(UriComponentsBuilder.newInstance()
703	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
704	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
705	    }
706	
707	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
708	    @Override
709	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
710	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
711	        if (currentOwner == null) {
712	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
713	        }
714	        currentOwner.setAddress(ownerFieldsDto.getAddress());
715	        currentOwner.setCity(ownerFieldsDto.getCity());
716	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
717	        currentOwner.setLastName(ownerFieldsDto.getLastName());
718	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
719	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
720	        this.clinicService.saveOwner(currentOwner);
721	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
722	    }
723	
724	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
725	    @Transactional
726	    @Override
727	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
728	        Owner owner = this.clinicService.findOwnerById(ownerId);
729	        if (owner == null) {
730	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
731	        }
732	        this.clinicService.deleteOwner(owner);
733	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
734	    }
735	
736	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
737	    @Override
738	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
739	        Owner owner = this.clinicService.findOwnerById(ownerId);
740	        if (owner == null) {
741	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
742	        }
743	        HttpHeaders headers = new HttpHeaders();
744	        Pet pet = petMapper.toPet(petFieldsDto);
745	        owner.setId(ownerId);
746	        pet.setOwner(owner);
747	        pet.getType().setName(null);
748	        this.clinicService.savePet(pet);
749	        PetDto petDto = petMapper.toPetDto(pet);
750	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
751	            .buildAndExpand(pet.getId()).toUri());
752	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
753	    }
754	
755	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
756	    @Override
757	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
758	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
759	        if (currentOwner != null) {
760	            Pet currentPet = this.clinicService.findPetById(petId);
761	            if (currentPet != null) {
762	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
763	                currentPet.setName(petFieldsDto.getName());
764	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
765	                this.clinicService.savePet(currentPet);
766	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
767	            }
768	        }
769	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
770	    }
771	
772	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
773	    @Override
774	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
775	        HttpHeaders headers = new HttpHeaders();
776	        Visit visit = visitMapper.toVisit(visitFieldsDto);
777	        Pet pet = new Pet();
778	        pet.setId(petId);
779	        visit.setPet(pet);
780	        this.clinicService.saveVisit(visit);
781	        VisitDto visitDto = visitMapper.toVisitDto(visit);
782	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
783	            .buildAndExpand(visit.getId()).toUri());
784	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
785	    }
786	
787	
788	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
789	    @Override
790	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
791	        Owner owner = this.clinicService.findOwnerById(ownerId);
792	        if (owner != null) {
793	            Pet pet = owner.getPet(petId);
794	            if (pet != null) {
795	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
796	            }
797	        }
798	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
799	    }
