 * Thrown when a request to create an owner resolves to the same household as an existing owner -
 * the household being keyed on the computed {@code householdId} derived from
 * {@code (lastName, postcode)} - and does not opt in via the {@code sharesHousehold} flag. The
 * exception handler translates it to a 409 Conflict whose {@code errors} array names the offending
 * {@code lastName} and {@code postcode} fields.
 */
public class DuplicateHouseholdException extends RuntimeException {

    public DuplicateHouseholdException(String lastName, String postcode) {
        super("Another owner already shares this household (lastName + postcode): "
            + lastName + " / " + postcode);
    }
}

